7	import { createRegistry, LogFileError, LeaseTakenError } from '../src/index.js';
8	
9	function fakeClock(start = 0) {
10	  let now = start;
11	  const clock = () => now;
12	  clock.set = (value) => {
13	    now = value;
14	  };
15	  return clock;
16	}
17	
18	let dir;
19	function logPath(name) {
20	  return path.join(dir, `${name}.log`);
21	}
22	function sabotage(p) {
23	  fs.renameSync(p, p + '.bak');
24	  fs.mkdirSync(p);
25	}
26	function restore(p) {
27	  fs.rmdirSync(p);
28	  fs.renameSync(p + '.bak', p);
29	}
30	
31	test.beforeEach(() => {
32	  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'lease-log-'));
33	});
34	
35	test.afterEach(() => {
36	  fs.rmSync(dir, { recursive: true, force: true });
37	});
