39	test('replay restores live leases and cumulative counters without extra counts', () => {
40	  const p = logPath('restart');
41	  const c1 = fakeClock(0);
42	  let r = createRegistry({ ttlMs: 100, clock: c1, logPath: p });
43	  const keep = r.acquire('keep', 'h1', 100);
44	  const renewed = r.acquire('renewed', 'h2', 40);
45	  const freed = r.acquire('freed', 'h3', 100);
46	  r.acquire('expired', 'h4', 10);
47	  c1.set(30);
48	  assert.equal(r.renew(renewed.token), true);
49	  assert.equal(r.release(freed.token), true);
50	  c1.set(50);
51	  assert.deepEqual(r.sweep(), ['expired']);
52	  assert.deepEqual(r.stats(), {
53	    granted: 4, renewed: 1, released: 1, reclaimed: 1, live: 2,
54	  });
55	
56	  const c2 = fakeClock(50);
57	  r = createRegistry({ ttlMs: 100, clock: c2, logPath: p });
58	
59	  assert.equal(r.holder('keep'), 'h1');
60	  assert.equal(r.holder('renewed'), 'h2');
61	  assert.equal(r.holder('freed'), null);
62	  assert.equal(r.holder('expired'), null);
63	  assert.deepEqual(r.stats(), {
64	    granted: 4, renewed: 1, released: 1, reclaimed: 1, live: 2,
65	  });
66	
67	  // Credentials issued before the restart are void.
68	  assert.equal(r.renew(keep.token), false);
69	  assert.equal(r.release(keep.token), false);
70	  assert.equal(r.renew(renewed.token), false);
71	  assert.equal(r.release(freed.token), false);
72	  assert.deepEqual(r.stats(), {
73	    granted: 4, renewed: 1, released: 1, reclaimed: 1, live: 2,
74	  });
75	});
