77	test('live replayed leases block acquisition after restart', () => {
78	  const p = logPath('blocked');
79	  let r = createRegistry({ ttlMs: 100, clock: fakeClock(0), logPath: p });
80	  r.acquire('r', 'a');
81	  r = createRegistry({ ttlMs: 100, clock: fakeClock(0), logPath: p });
82	
83	  assert.throws(
84	    () => r.acquire('r', 'b'),
85	    (e) => e instanceof LeaseTakenError && e.code === 'LEASE_TAKEN',
86	  );
87	  assert.equal(r.stats().granted, 1);
88	});
