90	test('after restart sweep reclaims in expiry order and counts once', () => {
91	  const p = logPath('sweep-order');
92	  const c = fakeClock(0);
93	  let r = createRegistry({ ttlMs: 100, clock: c, logPath: p });
94	  r.acquire('later', 'h', 50);
95	  r.acquire('earlier', 'h', 10);
96	  r.acquire('middle', 'h', 30);
97	
98	  r = createRegistry({ ttlMs: 100, clock: fakeClock(100), logPath: p });
99	  assert.deepEqual(r.sweep(), ['earlier', 'middle', 'later']);
100	  assert.deepEqual(r.sweep(), []);
101	  assert.equal(r.stats().reclaimed, 3);
