104	test('counters and liveness survive a second restart', () => {
105	  const p = logPath('twice');
106	  const c = fakeClock(0);
107	  let r = createRegistry({ ttlMs: 100, clock: c, logPath: p });
108	  const l = r.acquire('r', 'a', 200);
