// In-process, time bounded lease registry with append-only log persistence
// and crash-safe snapshots. Time only moves when the injected clock moves;
// nothing expires on its own. Tokens are derived from the injected clock as
// well, never from wall time.
//
// Persistence layout:
//   <logPath>           append-only event log, one JSON object per line
//   <logPath>.snapshot  last compacted state image (single JSON line)
// Startup loads the snapshot (if any) and then replays only the log bytes
// past the snapshot's offset. Compaction writes both files through a
// temp-file + fsync + rename sequence, so a failure at any step leaves the
// previous snapshot and the previous log usable. Every event carries a
// monotonic sequence number; a snapshot found next to an un-truncated
// original log (the swap died halfway) simply skips the events it already
// folded in, so the two swaps never have to commit as one atomic step.

import fs from 'node:fs';
import path from 'node:path';

const LOG_VERSION = 1;
const SNAPSHOT_VERSION = 1;

export class LeaseTakenError extends Error {
  constructor(resource, holder) {
    super(`lease for resource ${String(resource)} is already held`);
    this.name = 'LeaseTakenError';
    this.code = LeaseTakenError.code;
    this.resource = resource;
    this.holder = holder ?? null;
  }
}
LeaseTakenError.code = 'LEASE_TAKEN';

export class LogFileError extends Error {
  constructor(message, cause) {
    super(message);
    this.name = 'LogFileError';
    this.code = LogFileError.code;
    this.cause = cause ?? null;
  }
}
LogFileError.code = 'LOG_FILE_ERROR';

// Binary min-heap ordered by (expiresAt, insertion order). Every live lease
// has a node in the queue; renewals push a fresh node and retire the old one,
// so reclaiming expired leases only walks entries that are actually due
// instead of scanning the whole table.
class ExpiryQueue {
  constructor() {
    this.nodes = [];
  }

  get size() {
    return this.nodes.length;
  }

  push(node) {
    const nodes = this.nodes;
    nodes.push(node);
    let i = nodes.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (expiresBefore(nodes[i], nodes[parent])) {
        [nodes[i], nodes[parent]] = [nodes[parent], nodes[i]];
        i = parent;
      } else {
        break;
      }
    }
  }

  peek() {
    return this.nodes[0];
  }

  pop() {
    const nodes = this.nodes;
    const top = nodes[0];
    const last = nodes.pop();
    if (nodes.length > 0) {
      nodes[0] = last;
      let i = 0;
      for (;;) {
        const left = i * 2 + 1;
        const right = left + 1;
        let next = i;
        if (left < nodes.length && expiresBefore(nodes[left], nodes[next])) {
          next = left;
        }
        if (right < nodes.length && expiresBefore(nodes[right], nodes[next])) {
          next = right;
        }
        if (next === i) {
          break;
        }
        [nodes[i], nodes[next]] = [nodes[next], nodes[i]];
        i = next;
      }
    }
    return top;
  }
}

function expiresBefore(a, b) {
  if (a.expiresAt !== b.expiresAt) {
    return a.expiresAt < b.expiresAt;
  }
  return a.order < b.order;
}

// Binary min-heap of wait-request deadlines. Timeout cleanup pops due
// requests in deadline order instead of scanning every pending request, so
// a large waiting population costs O(expired * log n), never O(n) per call.
class DeadlineQueue {
  constructor() {
    this.nodes = [];
  }

  get size() {
    return this.nodes.length;
  }

  push(node) {
    const nodes = this.nodes;
    nodes.push(node);
    let i = nodes.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (deadlineBefore(nodes[i], nodes[parent])) {
        [nodes[i], nodes[parent]] = [nodes[parent], nodes[i]];
        i = parent;
      } else {
        break;
      }
    }
  }

  peek() {
    return this.nodes[0];
  }

  pop() {
    const nodes = this.nodes;
    const top = nodes[0];
    const last = nodes.pop();
    if (nodes.length > 0) {
      nodes[0] = last;
      let i = 0;
      for (;;) {
        const left = i * 2 + 1;
        const right = left + 1;
        let next = i;
        if (left < nodes.length && deadlineBefore(nodes[left], nodes[next])) {
          next = left;
        }
        if (right < nodes.length && deadlineBefore(nodes[right], nodes[next])) {
          next = right;
        }
        if (next === i) {
          break;
        }
        [nodes[i], nodes[next]] = [nodes[next], nodes[i]];
        i = next;
      }
    }
    return top;
  }
}

function deadlineBefore(a, b) {
  if (a.deadline !== b.deadline) {
    return a.deadline < b.deadline;
  }
  return a.tie < b.tie;
}

let registrySequence = 0;
let atomicFileSequence = 0;

export function createRegistry({ ttlMs, clock = Date.now, logPath = null } = {}) {
  if (!Number.isFinite(ttlMs) || ttlMs <= 0) {
    throw new TypeError('ttlMs must be a positive finite number');
  }
  if (typeof clock !== 'function') {
    throw new TypeError('clock must be a function');
  }

  const snapshotPath = logPath === null ? null : `${logPath}.snapshot`;
  const defaultTtlMs = ttlMs;
  // resource -> FIFO array of queue positions. A group request listing the
  // same resource twice occupies two consecutive positions in that queue.
  const waitQueues = new Map();
  // requestId -> group, while the request is still queued.
  const pendingGroups = new Map();
  // token -> { resource, holder, expiresAt, ttlMs, legacy, heapSeq }
  const leases = new Map();
  // Every token this instance knows about, including replayed credentials
  // that were already released or reclaimed, so a freshly minted token can
  // never reuse a dead credential's string.
  const knownTokens = new Set();
  // resource -> tokens currently occupying it. Usually one entry; an atomic
  // group listing one resource several times holds one credential per
  // occurrence, all belonging to the same request.
  const slots = new Map();
  const expiryQueue = new ExpiryQueue();
  // One node per queued wait request, ordered by wait deadline. Nodes outlive
  // their request only until the next lazy pop, flagged `dead`.
  const deadlineQueue = new DeadlineQueue();

  const counters = {
    granted: 0,
    renewed: 0,
    released: 0,
    reclaimed: 0,
  };

  // Per-instance identity makes tokens unique across registries living in the
  // same process; one instance can never present a token another owns.
  registrySequence += 1;
  const registryId = registrySequence;
  let tokenSequence = 0;
  let queueOrder = 0;
  let deadlineTie = 0;
  let requestSequence = 0;
  let batchSequence = 0;
  // Monotonic id stamped on every persisted event; a snapshot records the
  // last id it folded in, so a log still containing the folded prefix (the
  // log swap failed) replays those events as no-ops instead of twice.
  let eventSeq = 0;

  function mintToken(now, seq = tokenSequence) {
    // Pure candidate: nothing is committed until the event is on disk, so a
    // failed append rolls all the way back. Pids and instance ids can coincide
    // after a restart, so skip any sequence that collides with a credential
    // reconstructed from the log. The caller threads the sequence through when
    // it mints several tokens for one atomic write.
    let token;
    do {
      seq += 1;
      token = `lease-${process.pid}-${registryId}-${seq}-${now.toString(36)}`;
    } while (knownTokens.has(token));
    return { token, seq };
  }

  function enqueue(token, lease) {
    expiryQueue.push({
      token,
      expiresAt: lease.expiresAt,
      heapSeq: lease.heapSeq,
      order: queueOrder++,
    });
  }

  function isLive(lease, now) {
    return lease !== undefined && lease.expiresAt > now;
  }

  function getSlots(resource) {
    let list = slots.get(resource);
    if (list === undefined) {
      list = [];
      slots.set(resource, list);
    }
    return list;
  }

  function addSlot(resource, token) {
    getSlots(resource).push(token);
  }

  function removeSlot(resource, token) {
    const list = slots.get(resource);
    if (list === undefined) {
      return false;
    }
    const index = list.indexOf(token);
    if (index === -1) {
      return false;
    }
    list.splice(index, 1);
    if (list.length === 0) {
      slots.delete(resource);
    }
    return true;
  }

  // Drop expired-but-unswept credentials from a resource that is about to be
  // granted: the resource is free, and a retaken lease must never be reported
  // as reclaimed later. Mirrors the single-resource retake rule.
  function dropStaleSlots(resource, now) {
    const list = slots.get(resource);
    if (list === undefined) {
      return;
    }
    for (let i = list.length - 1; i >= 0; i -= 1) {
      const token = list[i];
      if (!isLive(leases.get(token), now)) {
        leases.delete(token);
        list.splice(i, 1);
      }
    }
    if (list.length === 0) {
      slots.delete(resource);
    }
  }

  function liveSlotCount(resource, now) {
    const list = slots.get(resource);
    if (list === undefined) {
      return 0;
    }
    let live = 0;
    for (const token of list) {
      if (isLive(leases.get(token), now)) {
        live += 1;
      }
    }
    return live;
  }

  function liveHolder(resource, now) {
    const list = slots.get(resource);
    if (list === undefined) {
      return null;
    }
    for (const token of list) {
      const lease = leases.get(token);
      if (isLive(lease, now)) {
        return lease.holder;
      }
    }
    return null;
  }

  function fsyncDirectory(file) {
    const dir = path.dirname(file);
    const fd = fs.openSync(dir, 'r');
    try {
      fs.fsyncSync(fd);
    } finally {
      fs.closeSync(fd);
    }
  }

  // Publish a file via temp + fsync + rename so the target is either the old
  // complete content or the new complete content, never a mixture. Any failure
  // leaves the target untouched and surfaces as an assertable LogFileError.
  function writeAtomic(target, content) {
    atomicFileSequence += 1;
    const tmp = `${target}.tmp-${process.pid}-${atomicFileSequence}`;
    try {
      const fd = fs.openSync(tmp, 'wx');
      try {
        fs.writeFileSync(fd, content, 'utf8');
        fs.fsyncSync(fd);
      } finally {
        fs.closeSync(fd);
      }
      fs.renameSync(tmp, target);
      fsyncDirectory(target);
    } catch (cause) {
      try {
        fs.rmSync(tmp, { force: true });
      } catch {
        // The original error is the one the caller must act on.
      }
      throw new LogFileError(
        `failed to write lease file ${target}`,
        cause,
      );
    }
  }

  function appendEvents(events) {
    if (logPath === null) {
      return;
    }
    // One write for the whole batch: an operation that frees resources and
    // wakes requests either lands completely or not at all.
    let text = '';
    for (const event of events) {
      eventSeq += 1;
      event.e = eventSeq;
      text += `${JSON.stringify(event)}\n`;
    }
    try {
      fs.appendFileSync(logPath, text);
    } catch (cause) {
      throw new LogFileError(
        `failed to append to lease log at ${logPath}`,
        cause,
      );
    }
  }

  function appendEvent(event) {
    appendEvents([event]);
  }

  function detachGroup(group) {
    for (const position of group.positions) {
      const queue = waitQueues.get(position.resource);
      if (queue === undefined) {
        continue;
      }
      const index = queue.indexOf(position);
      if (index !== -1) {
        queue.splice(index, 1);
        if (queue.length === 0) {
          waitQueues.delete(position.resource);
        }
      }
    }
    pendingGroups.delete(group.requestId);
    // Its deadline node retires lazily on the next purge.
    group.deadlineNode.dead = true;
  }

  // A queued request gives up once the clock reaches its deadline and is
  // never woken afterwards. Only the deadline heap is consulted: requests
  // that are still live are never even looked at, no matter how many wait.
  function purgeExpiredWaiters(now) {
    while (deadlineQueue.size > 0) {
      const node = deadlineQueue.peek();
      if (node.dead) {
        deadlineQueue.pop();
        continue;
      }
      if (node.deadline > now) {
        break;
      }
      deadlineQueue.pop();
      const group = pendingGroups.get(node.requestId);
      if (group === undefined || group.deadlineNode !== node) {
        continue;
      }
      detachGroup(group);
      group.ticket.status = 'expired';
    }
  }

  function enqueueGroup(resources, ttlList, holder, now, waitMs, single) {
    requestSequence += 1;
    const requestId = `wait-${registryId}-${requestSequence}`;
    const ticket = single
      // Exact baseline shape for single-resource callers.
      ? { status: 'waiting', resource: resources[0], holder, waitId: requestId }
      : { status: 'waiting', resources: [...resources], holder, waitId: requestId };
    deadlineTie += 1;
    const deadlineNode = { requestId, deadline: now + waitMs, tie: deadlineTie, dead: false };
    const group = {
      requestId,
      arrival: requestSequence,
      holder,
      deadline: now + waitMs,
      deadlineNode,
      single,
      ticket,
      positions: [],
    };
    deadlineQueue.push(deadlineNode);
    // One position per listed occurrence, pushed onto each resource's queue
    // in the given order. Positions of one request land consecutively, so a
    // repeated resource lines up as many times as it was listed.
    resources.forEach((resource, index) => {
      const position = {
        group,
        resource,
        ttlMs: ttlList[index],
        granted: false,
        token: null,
        expiresAt: null,
      };
      group.positions.push(position);
      let queue = waitQueues.get(resource);
      if (queue === undefined) {
        queue = [];
        waitQueues.set(resource, queue);
      }
      queue.push(position);
    });
    pendingGroups.set(requestId, group);
    return group;
  }

  // Plan every grant one request needs (one per still-ungranted position),
  // touching no state. The caller commits only after all events are on disk.
  // batchId ties the credentials of one atomic batch together for replay.
  function planGroupGrants(group, now, seqCursor) {
    const batchId = nextBatchId();
    const grants = [];
    let seq = seqCursor;
    for (const position of group.positions) {
      if (position.granted) {
        continue;
      }
      const minted = mintToken(now, seq);
      seq = minted.seq;
      const expiresAt = now + position.ttlMs;
      grants.push({
        position,
        group,
        resource: position.resource,
        holder: group.holder,
        ttlMs: position.ttlMs,
        token: minted.token,
        seq: minted.seq,
        expiresAt,
        event: {
          v: LOG_VERSION,
          type: 'acquire',
          at: now,
          token: minted.token,
          resource: position.resource,
          holder: group.holder,
          ttlMs: position.ttlMs,
          expiresAt,
          requestId: group.requestId,
          batch: batchId,
        },
      });
    }
    return { group, grants, seq, batchId };
  }

  function applyPlannedGrants(plan, now) {
    for (const grant of plan.grants) {
      tokenSequence = grant.seq;
      knownTokens.add(grant.token);
      const lease = {
        resource: grant.resource,
        holder: grant.holder,
        expiresAt: grant.expiresAt,
        ttlMs: grant.ttlMs,
        legacy: false,
        heapSeq: 0,
        batch: plan.batchId,
      };
      leases.set(grant.token, lease);
      dropStaleSlots(grant.resource, now);
      addSlot(grant.resource, grant.token);
      enqueue(grant.token, lease);
      counters.granted += 1;

      grant.position.token = grant.token;
      grant.position.expiresAt = grant.expiresAt;
      grant.position.granted = true;
    }

    // The batch holds everything it asked for; it leaves every queue at once.
    const { group } = plan;
    const { ticket } = group;
    detachGroup(group);
    ticket.status = 'granted';
    const granted = group.positions.map((position) => ({
      resource: position.resource,
      holder: group.holder,
      token: position.token,
      expiresAt: position.expiresAt,
    }));
    if (group.single) {
      ticket.token = granted[0].token;
      ticket.expiresAt = granted[0].expiresAt;
    } else {
      // One credential per listed occurrence, each with its own expiry.
      ticket.leases = granted;
      // Aliases for callers that read the batch outcome as a flat list.
      ticket.results = granted;
    }
  }

  function positionPlanned(plans, position) {
    return plans.some((plan) =>
      plan.grants.some((grant) => grant.position === position));
  }

  // A queued request is fillable exactly when every position reaches the
  // front of its resource's queue and that resource is free once the
  // triggering event is applied. Only live credentials occupy: an expired
  // but unswept lease is already gone, while a surviving twin of a released
  // duplicate credential keeps the resource held.
  function groupFillable(group, plans, freedLiveCount, now) {
    for (const position of group.positions) {
      if (position.granted) {
        continue;
      }
      const queue = waitQueues.get(position.resource);
      if (queue === undefined) {
        return false;
      }
      const index = queue.indexOf(position);
      for (let i = 0; i < index; i += 1) {
        const ahead = queue[i];
        if (ahead.group === group) {
          // Own repeated listing: its positions are granted together.
          continue;
        }
        if (positionPlanned(plans, ahead)) {
          continue;
        }
        return false;
      }
      // A release vacates a live credential; a sweep only removes leases
      // that were already expired, so it frees no live occupancy here.
      let occupied = Math.max(
        0,
        liveSlotCount(position.resource, now)
          - (freedLiveCount.get(position.resource) ?? 0),
      );
      for (const plan of plans) {
        if (plan.group === group) {
          continue;
        }
        for (const grant of plan.grants) {
          if (grant.resource === position.resource) {
            occupied += 1;
          }
        }
      }
      if (occupied > 0) {
        return false;
      }
    }
    return true;
  }

  // Grant every queued request whose resources become available through the
  // given freeing event, cascading across resources and queues. Entries are
  // { resource, live }: a release vacates a live credential, a reclaim only
  // removes one that had already expired. Everything planned rides in the
  // triggering log write.
  //
  // Only requests standing at the head of a queue touched by the event (plus
  // the requests exposed behind a batch planned in this cascade) can possibly
  // be fillable: a request was not fillable when it queued, and nothing else
  // changed. Wake planning therefore never inspects requests waiting on
  // unrelated resources, regardless of how many are queued in total.
  function planWakeups(freedEntries, now) {
    const freedLiveCount = new Map();
    const touched = new Set();
    for (const entry of freedEntries) {
      touched.add(entry.resource);
      if (entry.live) {
        freedLiveCount.set(
          entry.resource,
          (freedLiveCount.get(entry.resource) ?? 0) + 1,
        );
      }
    }
    const plans = [];
    const planned = new Set();
    const candidates = new Set();
    const seedHead = (resource) => {
      const queue = waitQueues.get(resource);
      if (queue !== undefined && queue.length > 0) {
        candidates.add(queue[0].group);
      }
    };
    for (const resource of touched) {
      seedHead(resource);
    }
    let seq = tokenSequence;
    for (;;) {
      // Candidates are picked strictly by arrival order: the earliest
      // pending request whose batch is now complete wins, so no resource's
      // queue can jump ahead of an earlier request.
      let next = null;
      for (const group of candidates) {
        if (planned.has(group)) {
          continue;
        }
        if (!groupFillable(group, plans, freedLiveCount, now)) {
          continue;
        }
        if (next === null || group.arrival < next.arrival) {
          next = group;
        }
      }
      if (next === null) {
        break;
      }
      const plan = planGroupGrants(next, now, seq);
      seq = plan.seq;
      plans.push(plan);
      planned.add(next);
      candidates.delete(next);
      // The granted batch leaves its queues; expose the first request behind
      // it on each resource it took, as a candidate for the same cascade.
      const resources = new Set(plan.grants.map((grant) => grant.resource));
      for (const resource of resources) {
        const queue = waitQueues.get(resource);
        if (queue === undefined) {
          continue;
        }
        for (const position of queue) {
          if (!planned.has(position.group)) {
            candidates.add(position.group);
            break;
          }
        }
      }
    }
    return plans;
  }

  function nextBatchId() {
    batchSequence += 1;
    return `batch-${registryId}-${batchSequence}`;
  }

  // Resolve the ttl argument into one positive finite ttl per occurrence.
  function resolveTtls(resources, ttlMs) {
    if (ttlMs === undefined) {
      return resources.map(() => defaultTtlMs);
    }
    if (Array.isArray(ttlMs)) {
      if (ttlMs.length !== resources.length) {
        throw new TypeError('ttlMs must match the resources list length');
      }
      return ttlMs.map((value) => {
        if (!Number.isFinite(value) || value <= 0) {
          throw new TypeError('ttlMs must be a positive finite number');
        }
        return value;
      });
    }
    if (!Number.isFinite(ttlMs) || ttlMs <= 0) {
      throw new TypeError('ttlMs must be a positive finite number');
    }
    return resources.map(() => ttlMs);
  }

  // Persist and commit one credential per listed occurrence, all in a single
  // log write. A failed write leaves every resource exactly as before.
  function commitDirectGrants(resources, ttlList, holder, now) {
    const batchId = nextBatchId();
    const events = [];
    const grants = [];
    let seq = tokenSequence;
    resources.forEach((resource, index) => {
      const ttlMsValue = ttlList[index];
      const minted = mintToken(now, seq);
      seq = minted.seq;
      const expiresAt = now + ttlMsValue;
      events.push({
        v: LOG_VERSION,
        type: 'acquire',
        at: now,
        token: minted.token,
        resource,
        holder,
        ttlMs: ttlMsValue,
        expiresAt,
        batch: batchId,
      });
      grants.push({ resource, ttlMs: ttlMsValue, token: minted.token, expiresAt });
    });
    appendEvents(events);

    tokenSequence = seq;
    const result = [];
    for (const grant of grants) {
      knownTokens.add(grant.token);
      const lease = {
        resource: grant.resource,
        holder,
        expiresAt: grant.expiresAt,
        ttlMs: grant.ttlMs,
        legacy: false,
        heapSeq: 0,
        batch: batchId,
      };
      leases.set(grant.token, lease);
      dropStaleSlots(grant.resource, now);
      addSlot(grant.resource, grant.token);
      enqueue(grant.token, lease);
      counters.granted += 1;
      result.push({
        resource: grant.resource,
        holder,
        token: grant.token,
        expiresAt: grant.expiresAt,
      });
    }
    return result;
  }

  // Atomic multi-resource acquisition. Every listed occurrence gets its own
  // credential and independent expiry; either all of them are held, or none
  // are (the whole request queues instead). ttlMs may be one number or one
  // ttl per listed resource.
  function acquireAll(resources, holder, ttlMs = undefined, waitMs = undefined) {
    if (!Array.isArray(resources) || resources.length === 0) {
      throw new TypeError('resources must be a non-empty array');
    }
    const ttlList = resolveTtls(resources, ttlMs);
    const wantsWait = validateWait(waitMs);
    const now = clock();
    purgeExpiredWaiters(now);

    // Earlier waiters keep their place, and any live lease on a listed
    // resource blocks the whole batch; a resource listed twice is free for
    // this request only when it is not held at all.
    let conflict = null;
    for (const resource of resources) {
      if (waitQueues.has(resource) || liveSlotCount(resource, now) > 0) {
        conflict = resource;
        break;
      }
    }

    if (conflict !== null) {
      if (!wantsWait) {
        throw new LeaseTakenError(conflict, liveHolder(conflict, now));
      }
      return enqueueGroup(
        resources, ttlList, holder, now, waitMs, false,
      ).ticket;
    }

    return commitDirectGrants(resources, ttlList, holder, now);
  }

  function validateWait(waitMs) {
    const wantsWait = waitMs !== undefined && waitMs !== null;
    if (wantsWait && (!Number.isFinite(waitMs) || waitMs <= 0)) {
      throw new TypeError('waitMs must be a positive finite number');
    }
    return wantsWait;
  }

  function acquire(resourceOrResources, holder, ttlMs = undefined, waitMs = undefined) {
    // Array input is the multi-resource form: same entry point, atomic rules.
    if (Array.isArray(resourceOrResources)) {
      return acquireAll(resourceOrResources, holder, ttlMs, waitMs);
    }
    const resource = resourceOrResources;
    const effectiveTtl = ttlMs === undefined ? defaultTtlMs : ttlMs;
    if (!Number.isFinite(effectiveTtl) || effectiveTtl <= 0) {
      throw new TypeError('ttlMs must be a positive finite number');
    }
    const wantsWait = validateWait(waitMs);
    const now = clock();
    purgeExpiredWaiters(now);

    if (liveSlotCount(resource, now) > 0 || waitQueues.has(resource)) {
      if (!wantsWait) {
        throw new LeaseTakenError(resource, liveHolder(resource, now));
      }
      // Occupied or reserved: take a place in line instead of throwing. The
      // resource does not change hands just because a waiter showed up.
      return enqueueGroup(
        [resource], [effectiveTtl], holder, now, waitMs, true,
      ).ticket;
    }

    const [granted] = commitDirectGrants(
      [resource], [effectiveTtl], holder, now,
    );
    return granted;
  }

  function renew(token) {
    const lease = leases.get(token);
    if (lease === undefined || lease.legacy) {
      return false;
    }
    const now = clock();
    if (lease.expiresAt <= now) {
      return false;
    }
    purgeExpiredWaiters(now);
    const expiresAt = now + lease.ttlMs;
    appendEvent({ v: LOG_VERSION, type: 'renew', at: now, token, expiresAt });

    lease.expiresAt = expiresAt;
    lease.heapSeq += 1;
    enqueue(token, lease);
    counters.renewed += 1;
    return true;
  }

  function release(token) {
    const lease = leases.get(token);
    if (lease === undefined || lease.legacy) {
      return false;
    }
    const now = clock();
    if (lease.expiresAt <= now) {
      return false;
    }
    purgeExpiredWaiters(now);

    // The freed resource goes to the requests at the head of its queue; a
    // group only wakes when every copy it needs is free. All wakeup grants
    // ride in the same write as the release, so a failed log leaves the lease
    // and every queue untouched.
    const plans = planWakeups([{ resource: lease.resource, live: true }], now);
    const events = [{ v: LOG_VERSION, type: 'release', at: now, token }];
    for (const plan of plans) {
      for (const grant of plan.grants) {
        events.push(grant.event);
      }
    }
    appendEvents(events);

    // The record comes off immediately; its queued node retires lazily.
    leases.delete(token);
    removeSlot(lease.resource, token);
    counters.released += 1;
    for (const plan of plans) {
      applyPlannedGrants(plan, now);
    }
    return true;
  }

  // Cancelling only lands on a request that is still queued: an already
  // woken, expired or cancelled request reports false, as does an unknown id.
  function cancel(requestId) {
    purgeExpiredWaiters(clock());
    const group = pendingGroups.get(requestId);
    if (group === undefined) {
      return false;
    }
    detachGroup(group);
    group.ticket.status = 'cancelled';
    return true;
  }

  function sweep(now = clock()) {
    purgeExpiredWaiters(now);
    const due = [];
    while (expiryQueue.size > 0) {
      const node = expiryQueue.peek();
      if (node.expiresAt > now) {
        break;
      }
      expiryQueue.pop();
      const lease = leases.get(node.token);
      if (lease === undefined || lease.heapSeq !== node.heapSeq) {
        // Retired node: release, retake or renewal already superseded it.
        continue;
      }
      due.push(node);
    }

    if (due.length === 0) {
      return [];
    }

    // Every due node still carries the current lease record (retired nodes
    // were filtered above) and a current lease always occupies its resource.
    const reclaimable = due;

    // Reclaimed resources are handed to the head requests of their queues in
    // the same expiry order the reclaim happens; every wakeup grant rides
    // along in the same log write, so a failed append rolls everything back.
    const events = [{
      v: LOG_VERSION,
      type: 'reclaim',
      at: now,
      items: reclaimable.map((node) => ({
        token: node.token,
        resource: leases.get(node.token).resource,
      })),
    }];
    const plans = planWakeups(
      reclaimable.map((node) => ({
        resource: leases.get(node.token).resource,
        live: false,
      })),
      now,
    );
    for (const plan of plans) {
      for (const grant of plan.grants) {
        events.push(grant.event);
      }
    }

    try {
      appendEvents(events);
    } catch (error) {
      // The write never happened: put the popped nodes back so the queue is
      // byte-for-byte the same as before the call.
      for (const node of due) {
        expiryQueue.push(node);
      }
      throw error;
    }

    const freed = [];
    for (const node of reclaimable) {
      const lease = leases.get(node.token);
      leases.delete(node.token);
      if (removeSlot(lease.resource, node.token)) {
        counters.reclaimed += 1;
        freed.push(lease.resource);
      }
    }
    for (const plan of plans) {
      applyPlannedGrants(plan, now);
    }
    return freed;
  }

  function holder(resource) {
    const now = clock();
    purgeExpiredWaiters(now);
    return liveHolder(resource, now);
  }

  function stats() {
    let live = 0;
    const now = clock();
    purgeExpiredWaiters(now);
    for (const list of slots.values()) {
      for (const token of list) {
        if (isLive(leases.get(token), now)) {
          live += 1;
        }
      }
    }
    return {
      granted: counters.granted,
      renewed: counters.renewed,
      released: counters.released,
      reclaimed: counters.reclaimed,
      live,
    };
  }

  // Fold the whole history into one snapshot and restart the event log from
  // that point. The snapshot is published first (temp + fsync + rename) and
  // the trimmed log second; a failure at either step leaves the previously
  // usable files in place and throws LogFileError. Credentials captured by
  // the snapshot are void afterwards, exactly as across a restart.
  function compact(now = clock()) {
    if (logPath === null) {
      throw new LogFileError('cannot compact a registry without a logPath');
    }

    // The offset must land right after the last complete line. A torn tail
    // from an interrupted append is discarded, just as on startup.
    let text = '';
    try {
      text = fs.readFileSync(logPath, 'utf8');
    } catch (cause) {
      if (cause.code !== 'ENOENT') {
        throw new LogFileError(`failed to read lease log at ${logPath}`, cause);
      }
    }
    const lastNewline = text.lastIndexOf('\n');
    const offset = lastNewline === -1 ? 0 : lastNewline + 1;

    // The image carries every lease still in the table, including expired
    // ones nobody has swept yet, so a sweep after compaction frees and counts
    // them in exactly the same order as before. Only live credentials show in
    // ownership and liveness either way.
    const leaseEntries = [];
    for (const [token, lease] of leases.entries()) {
      leaseEntries.push({
        token,
        resource: lease.resource,
        holder: lease.holder,
        expiresAt: lease.expiresAt,
        ttlMs: lease.ttlMs,
        batch: lease.batch ?? null,
      });
    }
    const snapshot = {
      v: SNAPSHOT_VERSION,
      type: 'snapshot',
      at: now,
      offset,
      eventSeq,
      batchSeq: batchSequence,
      counters: { ...counters },
      leases: leaseEntries,
    };

    // 1. Publish the snapshot. If this fails, nothing else has moved.
    writeAtomic(snapshotPath, `${JSON.stringify(snapshot)}\n`);
    // 2. Replace the log with just the bytes past the folded prefix (empty in
    //    the synchronous case). If the rename ever fails after a committed
    //    snapshot, startup skips the already-folded events by their sequence
    //    ids, so state still comes out exactly once.
    writeAtomic(logPath, text.slice(offset));

    return { offset, leases: leaseEntries.length };
  }

  // Credentials of the atomic batch currently being replayed: a batch takes
  // over a resource as one unit, so its own earlier credentials must not be
  // treated as the stale lease it replaces.
  let replayBatchId = null;
  let replayBatchTokens = new Set();
  // Highest batch/event number seen in the log, so ids minted after a restart
  // can never collide with an earlier process's.
  let replayMaxBatchSeq = 0;
  let replayMaxEventSeq = 0;

  load();
  batchSequence = Math.max(batchSequence, replayMaxBatchSeq);
  eventSeq = Math.max(eventSeq, replayMaxEventSeq);

  return {
    acquire,
    acquireAll,
    acquireGroup: acquireAll,
    acquireMany: acquireAll,
    renew,
    release,
    sweep,
    holder,
    stats,
    cancel,
    compact,
  };

  function load() {
    if (logPath === null) {
      return;
    }

    const snapshot = readSnapshot();
    if (snapshot === 'missing-content') {
      // An empty or payload-less snapshot declares the old history gone:
      // start from a brand-new log and remove the stale files.
      removeIfPresent(snapshotPath);
      removeIfPresent(logPath);
      return;
    }

    let text;
    try {
      text = fs.readFileSync(logPath, 'utf8');
    } catch (cause) {
      if (cause.code === 'ENOENT') {
        text = '';
      } else {
        throw new LogFileError(`failed to read lease log at ${logPath}`, cause);
      }
    }

    // A write that died mid-line leaves bytes after the final newline.
    // Complete entries stay in force; the unterminated fragment never
    // happened, and is trimmed so later appends start on a fresh line.
    const lastNewline = text.lastIndexOf('\n');
    const validLength = lastNewline === -1 ? 0 : lastNewline + 1;
    if (validLength < text.length) {
      try {
        fs.truncateSync(logPath, validLength);
      } catch (cause) {
        throw new LogFileError(
          `failed to trim torn tail from lease log at ${logPath}`,
          cause,
        );
      }
    }

    if (snapshot !== null) {
      if (snapshot.offset <= validLength) {
        applySnapshot(snapshot);
        replayText(text.slice(snapshot.offset, validLength), snapshot.offset, true);
        return;
      }
      // Offset beyond the log means the image does not match this log: treat
      // it as corrupt and fall back to replaying the original log in full.
    }
    replayText(text.slice(0, validLength), 0, false);
  }

  function removeIfPresent(file) {
    try {
      fs.rmSync(file, { force: true });
    } catch (cause) {
      if (cause.code !== 'ENOENT') {
        throw new LogFileError(`failed to remove stale lease file ${file}`, cause);
      }
    }
  }

  // Read and classify the snapshot file:
  //   null              no snapshot, or an unreadable/corrupt one that must
  //                     be ignored in favour of the original log
  //   'missing-content' empty or payload-less image: start a brand-new log
  //   object            a usable snapshot
  function readSnapshot() {
    let raw;
    try {
      raw = fs.readFileSync(snapshotPath, 'utf8');
    } catch (cause) {
      if (cause.code === 'ENOENT') {
        return null;
      }
      throw new LogFileError(`failed to read lease snapshot at ${snapshotPath}`, cause);
    }

    if (raw === '') {
      return 'missing-content';
    }

    let value;
    try {
      value = JSON.parse(raw);
    } catch {
      // Corrupt image: the original log remains the source of truth.
      return null;
    }

    if (
      value === null ||
      typeof value !== 'object' ||
      value.v !== SNAPSHOT_VERSION ||
      value.type !== 'snapshot'
    ) {
      // Unknown version or damaged envelope: fall back to the original log.
      return null;
    }

    if (
      value.counters === undefined ||
      value.leases === undefined ||
      value.offset === undefined
    ) {
      // Recognizable envelope with no payload: content is missing.
      return 'missing-content';
    }

    if (
      typeof value.counters !== 'object' ||
      value.counters === null ||
      !Array.isArray(value.leases) ||
      !Number.isInteger(value.offset) ||
      value.offset < 0 ||
      !Number.isFinite(value.at) ||
      (value.eventSeq !== undefined &&
        (!Number.isInteger(value.eventSeq) || value.eventSeq < 0)) ||
      (value.batchSeq !== undefined &&
        (!Number.isInteger(value.batchSeq) || value.batchSeq < 0))
    ) {
      return null;
    }

    for (const key of ['granted', 'renewed', 'released', 'reclaimed']) {
      if (!Number.isFinite(value.counters[key])) {
        return null;
      }
    }
    for (const entry of value.leases) {
      if (
        entry === null ||
        typeof entry !== 'object' ||
        typeof entry.token !== 'string' ||
        !Number.isFinite(entry.ttlMs) ||
        !Number.isFinite(entry.expiresAt)
      ) {
        // Damaged lease record: the image is untrustworthy, replay the log.
        return null;
      }
    }

    return value;
  }

  function applySnapshot(snapshot) {
    counters.granted = snapshot.counters.granted;
    counters.renewed = snapshot.counters.renewed;
    counters.released = snapshot.counters.released;
    counters.reclaimed = snapshot.counters.reclaimed;
    replayMaxEventSeq = snapshot.eventSeq ?? 0;
    replayMaxBatchSeq = snapshot.batchSeq ?? 0;
    for (const entry of snapshot.leases) {
      const lease = {
        resource: entry.resource,
        holder: entry.holder,
        expiresAt: entry.expiresAt,
        ttlMs: entry.ttlMs,
        // Credentials captured before this process started are void: the
        // lease keeps occupying the resource, but its token cannot renew or
        // release it.
        legacy: true,
        heapSeq: 0,
        batch: entry.batch ?? null,
      };
      leases.set(entry.token, lease);
      addSlot(entry.resource, entry.token);
      knownTokens.add(entry.token);
      enqueue(entry.token, lease);
    }
  }

  function replayText(text, byteOffset, foldedMode) {
    const lines = text.split('\n');
    const linesBefore = countLines(byteOffset);
    for (let i = 0; i < lines.length; i += 1) {
      const line = lines[i];
      if (line === '') {
        continue;
      }
      let event;
      try {
        event = JSON.parse(line);
      } catch (cause) {
        throw new LogFileError(
          `corrupt lease log entry on line ${linesBefore + i + 1} of ${logPath}`,
          cause,
        );
      }
      if (foldedMode) {
        // Events the snapshot already folded in carry no (or an older)
        // sequence id: the snapshot said how far the log had been folded,
        // so those bytes are skipped rather than applied a second time.
        if (
          event === null ||
          typeof event !== 'object' ||
          !Number.isInteger(event.e) ||
          event.e <= replayMaxEventSeq
        ) {
          continue;
        }
      }
      replayEvent(event, linesBefore + i + 1);
    }
  }

  function countLines(byteOffset) {
    if (byteOffset === 0) {
      return 0;
    }
    // Only needed for error messages; startup reads the file once anyway.
    return 0;
  }

  function replayEvent(event, lineNumber) {
    if (event === null || typeof event !== 'object' || event.v !== LOG_VERSION) {
      throw new LogFileError(
        `unrecognized lease log version on line ${lineNumber} of ${logPath}`,
      );
    }
    if (Number.isInteger(event.e)) {
      replayMaxEventSeq = Math.max(replayMaxEventSeq, event.e);
    }

    switch (event.type) {
      case 'acquire': {
        if (
          typeof event.token !== 'string' ||
          !Number.isFinite(event.ttlMs) ||
          !Number.isFinite(event.expiresAt)
        ) {
          throw new LogFileError(
            `corrupt acquire entry on line ${lineNumber} of ${logPath}`,
          );
        }
        // Credentials minted together for one atomic batch superseded any
        // expired, unswept lease on the resource as one unit: only slots held
        // by a different batch count as the stale lease being retaken.
        if (event.batch !== undefined && event.batch !== null) {
          const logged = /^batch-[^-]+-(\d+)$/.exec(String(event.batch));
          if (logged !== null) {
            replayMaxBatchSeq = Math.max(
              replayMaxBatchSeq,
              Number(logged[1]),
            );
          }
          if (event.batch !== replayBatchId) {
            replayBatchId = event.batch;
            replayBatchTokens = new Set();
          }
        } else {
          replayBatchId = null;
          replayBatchTokens = new Set();
        }
        const occupantTokens = slots.get(event.resource);
        if (occupantTokens !== undefined) {
          for (const oldToken of [...occupantTokens]) {
            if (!replayBatchTokens.has(oldToken)) {
              leases.delete(oldToken);
              removeSlot(event.resource, oldToken);
            }
          }
        }
        const lease = {
          resource: event.resource,
          holder: event.holder,
          expiresAt: event.expiresAt,
          ttlMs: event.ttlMs,
          // Credentials issued before this process started are void: the
          // lease keeps occupying the resource, but its token cannot
          // renew or release it.
          legacy: true,
          heapSeq: 0,
          batch: event.batch ?? null,
        };
        leases.set(event.token, lease);
        addSlot(event.resource, event.token);
        replayBatchTokens.add(event.token);
        knownTokens.add(event.token);
        enqueue(event.token, lease);
        counters.granted += 1;
        break;
      }
      case 'renew': {
        if (
          typeof event.token !== 'string' ||
          !Number.isFinite(event.expiresAt)
        ) {
          throw new LogFileError(
            `corrupt renew entry on line ${lineNumber} of ${logPath}`,
          );
        }
        const lease = leases.get(event.token);
        if (lease !== undefined) {
          lease.expiresAt = event.expiresAt;
          lease.heapSeq += 1;
          enqueue(event.token, lease);
        }
        counters.renewed += 1;
        break;
      }
      case 'release': {
        if (typeof event.token !== 'string') {
          throw new LogFileError(
            `corrupt release entry on line ${lineNumber} of ${logPath}`,
          );
        }
        const lease = leases.get(event.token);
        if (lease !== undefined) {
          leases.delete(event.token);
          removeSlot(lease.resource, event.token);
        }
        counters.released += 1;
        break;
      }
      case 'reclaim': {
        if (!Array.isArray(event.items)) {
          throw new LogFileError(
            `corrupt reclaim entry on line ${lineNumber} of ${logPath}`,
          );
        }
        for (const item of event.items) {
          if (item === null || typeof item !== 'object' ||
              typeof item.token !== 'string') {
            throw new LogFileError(
              `corrupt reclaim entry on line ${lineNumber} of ${logPath}`,
            );
          }
          const token = item.token;
          const lease = leases.get(token);
          if (lease !== undefined) {
            leases.delete(token);
            removeSlot(lease.resource, token);
          }
          counters.reclaimed += 1;
        }
        break;
      }
      default: {
        throw new LogFileError(
          `unknown lease log event type on line ${lineNumber} of ${logPath}`,
        );
      }
    }
  }
}

