const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'stress-'));
function mulberry(seed) {
  return () => {
    seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const holders = ['a', 'b', 'c'];
const resources = ['r1', 'r2', 'r3', 'r4'];

function runTrial(trial) {
  const rnd = mulberry(trial * 99991 + 7);
  const pA = path.join(dir, `a${trial}.log`);
  const pB = path.join(dir, `b${trial}.log`);
  const t = { v: 0 };
  const clock = () => t.v;
  let A = createRegistry({ ttlMs: 100, clock, logPath: pA });
  let B = createRegistry({ ttlMs: 100, clock, logPath: pB });
  const toksA = [], toksB = [];
  const ticksA = [], ticksB = [];

  function compare(label) {
    assert.deepEqual(B.stats(), A.stats(), `stats mismatch trial ${trial} @ ${label}`);
    for (const r of resources) {
      assert.equal(B.holder(r), A.holder(r), `holder ${r} mismatch trial ${trial} @ ${label}`);
    }
    for (let i = 0; i < ticksA.length; i++) {
      assert.equal(ticksB[i].status, ticksA[i].status, `ticket ${i} mismatch trial ${trial} @ ${label}`);
    }
  }

  function restart(label) {
    A = createRegistry({ ttlMs: 100, clock, logPath: pA });
    B.compact();
    B = createRegistry({ ttlMs: 100, clock, logPath: pB });
    compare(label);
  }

  // Pre-draw the whole op so both registries see identical inputs.
  function drawOp() {
    const k = rnd();
    const jump = Math.floor(rnd() * 40);
    if (k < 0.5) {
      const h = holders[Math.floor(rnd() * holders.length)];
      const useGroup = rnd() < 0.3;
      const wait = rnd() < 0.35 ? 1 + Math.floor(rnd() * 200) : undefined;
      if (useGroup) {
        const n = 1 + Math.floor(rnd() * 2);
        const list = Array.from({ length: n }, () => resources[Math.floor(rnd() * resources.length)]);
        const ttl = list.map(() => 10 + Math.floor(rnd() * 180));
        return { kind: 'group', list, ttl, h, wait, jump };
      }
      const res = resources[Math.floor(rnd() * resources.length)];
      const ttl = 10 + Math.floor(rnd() * 180);
      return { kind: 'single', res, ttl, h, wait, jump };
    }
    if (k < 0.62) return { kind: 'renew', jump };
    if (k < 0.72) return { kind: 'release', jump };
    if (k < 0.82) return { kind: 'cancel', jump };
    return { kind: 'sweep', jump };
  }

  function apply(reg, op, toks, ticks) {
    if (op.kind === 'group') {
      const out = reg.acquireAll(op.list, op.h, op.ttl, op.wait);
      if (Array.isArray(out)) out.forEach((l) => toks.push(l.token));
      else ticks.push(out);
    } else if (op.kind === 'single') {
      const out = reg.acquire(op.res, op.h, op.ttl, op.wait);
      if (out.token) toks.push(out.token);
      else ticks.push(out);
    } else if (op.kind === 'renew' && toks.length) {
      reg.renew(toks[op.idx]);
    } else if (op.kind === 'release' && toks.length) {
      reg.release(toks[op.idx]);
    } else if (op.kind === 'cancel' && ticks.length) {
      return reg.cancel(ticks[op.idx].waitId);
    } else if (op.kind === 'sweep') {
      return reg.sweep();
    }
    return null;
  }

  for (let i = 0; i < 400; i++) {
    const op = drawOp();
    t.v += op.jump;
    if ((op.kind === 'renew' || op.kind === 'release') && toksA.length) {
      op.idx = Math.floor(rnd() * toksA.length);
    }
    if (op.kind === 'cancel' && ticksA.length && rnd() < 0.5) {
      op.idx = Math.floor(rnd() * ticksA.length);
    } else if (op.kind === 'cancel') {
      op.kind = 'sweep';
    }
    const ra = apply(A, op, toksA, ticksA);
    const rb = apply(B, op, toksB, ticksB);
    if (op.kind === 'sweep') {
      assert.deepEqual(rb, ra, `sweep order mismatch trial ${trial} op ${i}`);
    }
    if (op.kind === 'cancel') {
      assert.equal(rb, ra, `cancel mismatch trial ${trial} op ${i}`);
    }
    if (i % 25 === 24) compare(`op ${i}`);
    if (i % 90 === 89) restart(`restart op ${i}`);
  }
  for (let v = t.v; v <= t.v + 400; v += 20) {
    t.v = v;
    assert.deepEqual(B.sweep(), A.sweep(), `tail sweep @${v} trial ${trial}`);
  }
  restart('final');
}

for (let trial = 0; trial < 40; trial++) runTrial(trial);
fs.rmSync(dir, { recursive: true, force: true });
console.log('all 40 randomized trials matched');
